        # matrix, both in row-major order.
        if len(a_data) != rows * inner:
            raise ValueError("matmul_rect left length must equal rows * inner")
        if len(b_data) != inner * cols:
            raise ValueError(
                "matmul_rect right length must equal inner * cols"
            )
