                if not math.isfinite(half_delta):
                    raise ValueError(
                        "huber_loss intermediate must be finite"
                    )
                shifted = a_i - half_delta
                if not math.isfinite(shifted):
                    raise ValueError(
                        "huber_loss intermediate must be finite"
                    )
                term = delta * shifted
