                                "binary_cross_entropy_with_logits backward"
                                " intermediate must be finite"
                            )
                        denominator = 1.0 + e
                        if not math.isfinite(denominator):
                            raise ValueError(
                                "binary_cross_entropy_with_logits backward"
                                " intermediate must be finite"
                            )
                        s_i = e / denominator
                    if not math.isfinite(s_i):
                        raise ValueError(
                            "binary_cross_entropy_with_logits backward"
                            " intermediate must be finite"
                        )
