                    if not math.isfinite(scaled_x):
                        raise ValueError(
                            "binary_cross_entropy_with_logits backward"
                            " intermediate must be finite"
                        )
                    dx_i = scaled_x / n
                    if not math.isfinite(dx_i):
                        raise ValueError(
                            "binary_cross_entropy_with_logits backward"
                            " intermediate must be finite"
                        )
